        resultDiv.textContent = `🎉 Perfect! You got ${totalCorrect}/${totalQuestions} (${percentage}%)`;
    } else if (totalCorrect >= 1) {
        resultDiv.classList.add('partial');
        resultDiv.textContent = `Good effort! You got ${totalCorrect}/${totalQuestions} (${percentage}%)`;
    } else {
        resultDiv.classList.add('error');
        resultDiv.textContent = `Keep learning! You got ${totalCorrect}/${totalQuestions} (${percentage}%)`;
    }

    resultDiv.style.display = 'block';
});
